insert into public.hobbies(slug,name,content) values('tennis','Tennis','{"id":"tennis","name":"Tennis","icon":"🎾","color":"#D98C8C","description":"Find your rhythm. One rally at a time.","prefix":"ten","safetyNote":"Check the court, warm up gently, keep clear of others and stop if you feel pain.","resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["ten-safety"],"startSummary":"Borrow a racquet · TECHNIQUE-HEAVY"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('cycling','Cycling / Fixed Gear','{"id":"cycling","name":"Cycling / Fixed Gear","icon":"🚲","color":"#D6B65C","description":"A little farther. A little more freedom.","prefix":"cyc","safetyNote":"Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding.","resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["cyc-safety","cyc-check"],"startSummary":"Bike + helmet · GEAR NEEDED"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('swimming','Swimming','{"id":"swimming","name":"Swimming","icon":"🏊","color":"#72B7A4","description":"Build confidence, one length at a time.","prefix":"swi","safetyNote":"Practice with qualified supervision in a swim-safe environment. Never swim alone, hyperventilate or do breath-holding contests. Restrictive knee bands are not a default freestyle correction.","resources":[{"title":"Red Cross Adult Swim Lessons","url":"https://www.redcross.org/take-a-class/swimming/swim-lessons/adult-swim-lessons","placeholder":false,"checkedAt":"2026-09-21"},{"title":"MySwimPro: How to swim freestyle for beginners","url":"https://blog.myswimpro.com/2021/06/04/how-to-swim-freestyle-for-beginners-5-step-guide/","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["swi-safety"],"startSummary":"Pool + supervision · SAFETY FIRST"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('journaling','Journaling','{"id":"journaling","name":"Journaling","icon":"📔","color":"#AE9BC8","description":"Make a little space for your thoughts.","prefix":"jou","safetyNote":"","resources":[{"title":"Bullet Journal: How to start a simple bullet journal","url":"https://bulletjournal.com/blogs/bulletjournalist/how-to-start-a-simple-bullet-journal","placeholder":false,"checkedAt":"2026-09-21"},{"title":"UC Berkeley Greater Good in Action: Expressive writing","url":"https://ggia.berkeley.edu/practice/expressive_writing","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":[],"startSummary":"Existing paper + pen · EASY TO START"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('pc-building','PC Building','{"id":"pc-building","name":"PC Building","icon":"🖥️","color":"#7E93A8","description":"Understand the machine, then build it.","prefix":"pcb","safetyNote":"Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged.","resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["pcb-safety"],"startSummary":"Parts + one screwdriver · PLAN FIRST"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('drawing','Drawing','{"id":"drawing","name":"Drawing","icon":"✏️","color":"#A8998A","description":"Look closely. The hand follows.","prefix":"drw","safetyNote":"Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches.","resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":[],"startSummary":"Pencil and paper · FREE TO TRY"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('painting','Painting','{"id":"painting","name":"Painting","icon":"🎨","color":"#C98B6B","description":"Mix it, and see what the colour really is.","prefix":"pnt","safetyNote":"Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn.","resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["pnt-safety"],"startSummary":"Three colours + a brush · LOW COST"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('running','Running','{"id":"running","name":"Running","icon":"🏃","color":"#7FA86B","description":"Slower than you think. Further than you expect.","prefix":"run","safetyNote":"Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop.","resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["run-safety"],"startSummary":"Comfortable shoes · FREE TO TRY"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('volleyball','Volleyball','{"id":"volleyball","name":"Volleyball","icon":"🏐","color":"#E0B15C","description":"Three touches, and everyone is involved.","prefix":"vol","safetyNote":"Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides.","resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":["vol-safety"],"startSummary":"Mostly borrowed · JOIN A SESSION"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.hobbies(slug,name,content) values('reading','Reading','{"id":"reading","name":"Reading","icon":"📖","color":"#8FA9A0","description":"A few pages, most days.","prefix":"rdg","safetyNote":"Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime.","resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}],"practicePrerequisites":[],"startSummary":"A library card · FREE TO TRY"}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-start','Welcome to Tennis','{"id":"ten-start","hobbyId":"tennis","slug":"ten-start","title":"Welcome to Tennis","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read overview and choose a first goal","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":450,"y":0},"shortDescription":"Tennis rewards control and cooperation before power.","whyItMatters":"Tennis rewards control and cooperation before power.","instructions":["Choose a wall or beginner-friendly court","Set a small goal, such as making clean contact","Arrange a relaxed first session."],"learningObjectives":["Choose a wall or beginner-friendly court","Read overview and choose a first goal","Recognize and avoid the common mistake below."],"commonMistakes":["Trying to hit hard before finding a repeatable contact point."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-gear','First Racquet & Balls','{"id":"ten-gear","hobbyId":"tennis","slug":"ten-gear","title":"First Racquet & Balls","tier":"start","nodeType":"gear","xpReward":30,"requires":["ten-start"],"orGroups":[],"completion":{"prompt":"Record owned/borrowed racquet and balls","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Athletics","Knowledge"],"category":"Gear","position":{"x":180,"y":150},"shortDescription":"Simple, usable equipment gets you on court sooner.","whyItMatters":"Simple, usable equipment gets you on court sooner.","instructions":["Borrow a comfortable racquet if possible","Find tennis balls appropriate to your level","Record the racquet and balls in Loadout."],"learningObjectives":["Borrow a comfortable racquet if possible","Record owned/borrowed racquet and balls","Recognize and avoid the common mistake below."],"commonMistakes":["Buying several expensive racquets before learning your preferences."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-safety','Court Safety & Etiquette','{"id":"ten-safety","hobbyId":"tennis","slug":"ten-safety","title":"Court Safety & Etiquette","tier":"start","nodeType":"orientation","xpReward":30,"requires":["ten-start"],"orGroups":[],"completion":{"prompt":"Complete safety checklist","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":450,"y":150},"shortDescription":"Shared space works best when everyone can move safely.","whyItMatters":"Shared space works best when everyone can move safely.","instructions":["Check the surface for water and loose balls","Warm up with gentle movement","Wait for a point to finish before crossing","Keep racquets clear of others and stop for pain."],"learningObjectives":["Check the surface for water and loose balls","Complete safety checklist","Recognize and avoid the common mistake below."],"commonMistakes":["Chasing a loose ball onto an occupied court."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-scoring','Court, Rules & Scoring','{"id":"ten-scoring","hobbyId":"tennis","slug":"ten-scoring","title":"Court, Rules & Scoring","tier":"start","nodeType":"orientation","xpReward":30,"requires":["ten-start"],"orGroups":[],"completion":{"prompt":"Correctly log a sample game score","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":720,"y":150},"shortDescription":"Knowing the score keeps your attention on the next point.","whyItMatters":"Knowing the score keeps your attention on the next point.","instructions":["Trace the baseline, service boxes and sidelines","Practice love, 15, 30, 40, game","Write a sample game including deuce and advantage","Agree on scoring with a partner."],"learningObjectives":["Trace the baseline, service boxes and sidelines","Correctly log a sample game score","Recognize and avoid the common mistake below."],"commonMistakes":["Confusing a game with a set."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-grip','Grip & Ready Position','{"id":"ten-grip","hobbyId":"tennis","slug":"ten-grip","title":"Grip & Ready Position","tier":"beginner","nodeType":"lesson","xpReward":50,"requires":["ten-gear","ten-safety"],"orGroups":[],"completion":{"prompt":"Demonstrate/confirm ready position for 10 reps","evidenceMode":"count","targetValue":10,"targetUnit":"repetitions"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Athletics","Knowledge"],"category":"Technique","position":{"x":450,"y":300},"shortDescription":"A balanced ready position makes the next movement easier.","whyItMatters":"A balanced ready position makes the next movement easier.","instructions":["Ask a coach to check a comfortable beginner grip","Stand with soft knees and racquet in front","Reset after each of ten relaxed repetitions."],"learningObjectives":["Ask a coach to check a comfortable beginner grip","Demonstrate/confirm ready position for 10 reps","Recognize and avoid the common mistake below."],"commonMistakes":["Squeezing the handle so tightly that movement becomes stiff."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-contact','Contact & Ball Tracking','{"id":"ten-contact","hobbyId":"tennis","slug":"ten-contact","title":"Contact & Ball Tracking","tier":"beginner","nodeType":"practice","xpReward":60,"requires":["ten-grip"],"orGroups":[],"completion":{"prompt":"Self-drop and contact 20 balls under control","evidenceMode":"count","targetValue":20,"targetUnit":"repetitions"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Athletics","Knowledge"],"category":"Practice","position":{"x":315,"y":450},"shortDescription":"Watching the ball helps you find consistent contact.","whyItMatters":"Watching the ball helps you find consistent contact.","instructions":["Use a clear court or wall area","Drop a ball beside you","Make a small controlled swing","Reset and repeat for twenty contacts."],"learningObjectives":["Use a clear court or wall area","Self-drop and contact 20 balls under control","Recognize and avoid the common mistake below."],"commonMistakes":["Taking a full-power swing on every attempt."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-forehand','Forehand Fundamentals','{"id":"ten-forehand","hobbyId":"tennis","slug":"ten-forehand","title":"Forehand Fundamentals","tier":"beginner","nodeType":"challenge","xpReward":100,"requires":["ten-contact"],"orGroups":[],"completion":{"prompt":"Land 10 controlled forehands in court","evidenceMode":"count","targetValue":10,"targetUnit":"repetitions"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Athletics","Knowledge"],"category":"Practice","position":{"x":180,"y":600},"shortDescription":"Control gives your forehand a useful foundation.","whyItMatters":"Control gives your forehand a useful foundation.","instructions":["Warm up with gentle feeds","Turn your shoulders before the bounce","Meet the ball comfortably in front","Count ten shots landing inside the court."],"learningObjectives":["Warm up with gentle feeds","Land 10 controlled forehands in court","Recognize and avoid the common mistake below."],"commonMistakes":["Reaching late instead of moving to the ball."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-backhand','Backhand Fundamentals','{"id":"ten-backhand","hobbyId":"tennis","slug":"ten-backhand","title":"Backhand Fundamentals","tier":"beginner","nodeType":"challenge","xpReward":100,"requires":["ten-contact"],"orGroups":[],"completion":{"prompt":"Land 10 controlled backhands in court","evidenceMode":"count","targetValue":10,"targetUnit":"repetitions"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Athletics","Knowledge"],"category":"Practice","position":{"x":450,"y":600},"shortDescription":"A dependable second side keeps a rally alive.","whyItMatters":"A dependable second side keeps a rally alive.","instructions":["Choose a comfortable one- or two-handed backhand with guidance","Start with slow feeds","Prepare early and finish balanced","Count ten controlled balls in court."],"learningObjectives":["Choose a comfortable one- or two-handed backhand with guidance","Land 10 controlled backhands in court","Recognize and avoid the common mistake below."],"commonMistakes":["Changing grip and technique on every ball."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-footwork','Split Step & Recovery','{"id":"ten-footwork","hobbyId":"tennis","slug":"ten-footwork","title":"Split Step & Recovery","tier":"beginner","nodeType":"practice","xpReward":75,"requires":["ten-grip"],"orGroups":[],"completion":{"prompt":"Complete three 60-second shadow-footwork rounds","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":8,"tags":["Athletics","Knowledge"],"category":"Practice","position":{"x":585,"y":450},"shortDescription":"Recovering after a shot prepares you for the next one.","whyItMatters":"Recovering after a shot prepares you for the next one.","instructions":["Use an empty court without a ball","Make a small split step as an imagined opponent contacts","Move, shadow a shot, and recover","Do three gentle sixty-second rounds with rest."],"learningObjectives":["Use an empty court without a ball","Complete three 60-second shadow-footwork rounds","Recognize and avoid the common mistake below."],"commonMistakes":["Landing stiff-legged or rushing beyond balance."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='tennis'),'ten-rally5','Five-Shot Rally','{"id":"ten-rally5","hobbyId":"tennis","slug":"ten-rally5","title":"Five-Shot Rally","tier":"beginner","nodeType":"milestone","xpReward":150,"requires":["ten-forehand","ten-backhand","ten-footwork"],"orGroups":[],"completion":{"prompt":"Sustain five cooperative shots","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":9,"tags":["Athletics","Knowledge"],"category":"Milestones","position":{"x":315,"y":750},"shortDescription":"Cooperative rallies turn isolated strokes into play.","whyItMatters":"Cooperative rallies turn isolated strokes into play.","instructions":["Choose a partner and a comfortable distance","Aim toward each other","Count consecutive controlled shots","Log a rally of five."],"learningObjectives":["Choose a partner and a comfortable distance","Sustain five cooperative shots","Recognize and avoid the common mistake below."],"commonMistakes":["Trying to win a cooperative drill."],"safetyNotes":["Check the court, warm up gently, keep clear of others and stop if you feel pain."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USTA Tennis 101","url":"https://www.usta.com/en/home/stay-current/midwest/tennis101.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Intuitive Tennis: Beginner forehand and two-handed backhand (video)","url":"https://www.youtube.com/watch?v=kbmsyOGR6Cc","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
