insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='cycling'),'cyc-start','Welcome to Cycling','{"id":"cyc-start","hobbyId":"cycling","slug":"cyc-start","title":"Welcome to Cycling","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Choose riding goal and environment","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":19,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":450,"y":0},"shortDescription":"Matching your ride to your environment makes starting simpler.","whyItMatters":"Matching your ride to your environment makes starting simpler.","instructions":["Choose transport, leisure or fitness as a goal","Identify a quiet practice area","Arrange a bike and a safe first session."],"learningObjectives":["Choose transport, leisure or fitness as a goal","Choose riding goal and environment","Recognize and avoid the common mistake below."],"commonMistakes":["Starting in busy traffic before learning control."],"safetyNotes":["Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
