insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='cycling'),'cyc-safety','Helmet, Visibility & Traffic Safety','{"id":"cyc-safety","hobbyId":"cycling","slug":"cyc-safety","title":"Helmet, Visibility & Traffic Safety","tier":"start","nodeType":"orientation","xpReward":40,"requires":["cyc-start"],"orGroups":[],"completion":{"prompt":"Complete mandatory safety checklist","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":22,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":720,"y":150},"shortDescription":"Visibility, road awareness and reliable brakes come before distance.","whyItMatters":"Visibility, road awareness and reliable brakes come before distance.","instructions":["Use a correctly fitted certified helmet","Check lights and reflectors","Learn local traffic rules from your road authority","Plan a quiet route and communicate turns","Keep a functional front brake on a road-going fixed gear."],"learningObjectives":["Use a correctly fitted certified helmet","Complete mandatory safety checklist","Recognize and avoid the common mistake below."],"commonMistakes":["Assuming drivers have seen you or relying on skids to stop."],"safetyNotes":["Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='cycling'),'cyc-fit','Basic Bike Fit','{"id":"cyc-fit","hobbyId":"cycling","slug":"cyc-fit","title":"Basic Bike Fit","tier":"start","nodeType":"gear","xpReward":40,"requires":["cyc-anatomy"],"orGroups":[],"completion":{"prompt":"Record saddle height check and reach comfort","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":23,"tags":["Athletics","Knowledge"],"category":"Gear","position":{"x":315,"y":300},"shortDescription":"A comfortable starting fit supports control.","whyItMatters":"A comfortable starting fit supports control.","instructions":["With support, check you can reach the brakes comfortably","Check saddle height with a qualified shop if uncertain","Make small changes and record comfort","Check that all adjusted fasteners are secure."],"learningObjectives":["With support, check you can reach the brakes comfortably","Record saddle height check and reach comfort","Recognize and avoid the common mistake below."],"commonMistakes":["Making large changes or guessing torque limits."],"safetyNotes":["Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='cycling'),'cyc-check','Pre-Ride ABC Check','{"id":"cyc-check","hobbyId":"cycling","slug":"cyc-check","title":"Pre-Ride ABC Check","tier":"beginner","nodeType":"maintenance","xpReward":50,"requires":["cyc-safety","cyc-anatomy"],"orGroups":[],"completion":{"prompt":"Perform air/brakes/chain check","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":24,"tags":["Athletics","Knowledge"],"category":"Maintenance","position":{"x":585,"y":300},"shortDescription":"A short check can catch a problem before it becomes a ride problem.","whyItMatters":"A short check can catch a problem before it becomes a ride problem.","instructions":["Check Air against the tire guidance","Test both Brakes while walking the bike","Inspect Chain and cranks for obvious problems","Check wheel security and take a short test roll."],"learningObjectives":["Check Air against the tire guidance","Perform air/brakes/chain check","Recognize and avoid the common mistake below."],"commonMistakes":["Riding with a brake fault instead of repairing it."],"safetyNotes":["Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slu