insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='cycling'),'cyc-control','Starting, Stopping & Steering','{"id":"cyc-control","hobbyId":"cycling","slug":"cyc-control","title":"Starting, Stopping & Steering","tier":"beginner","nodeType":"practice","xpReward":60,"requires":["cyc-fit","cyc-check"],"orGroups":[],"completion":{"prompt":"Complete 20-minute low-traffic control session","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":25,"tags":["Athletics","Knowledge"],"category":"Practice","position":{"x":450,"y":450},"shortDescription":"Quiet practice builds predictable handling.","whyItMatters":"Quiet practice builds predictable handling.","instructions":["Choose a traffic-free level area","Practice starting, looking ahead and broad turns","Stop smoothly using functional brakes","Spend twenty minutes at a comfortable pace."],"learningObjectives":["Choose a traffic-free level area","Complete 20-minute low-traffic control session","Recognize and avoid the common mistake below."],"commonMistakes":["Looking down at the front wheel."],"safetyNotes":["Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='cycling'),'cyc-brake','Controlled Braking','{"id":"cyc-brake","hobbyId":"cycling","slug":"cyc-brake","title":"Controlled Braking","tier":"beginner","nodeType":"challenge","xpReward":75,"requires":["cyc-control"],"orGroups":[],"completion":{"prompt":"Complete 10 smooth controlled stops","evidenceMode":"count","targetValue":10,"targetUnit":"repetitions"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":26,"tags":["Athletics","Knowledge"],"category":"Practice","position":{"x":450,"y":600},"shortDescription":"Predictable stopping is more useful than speed.","whyItMatters":"Predictable stopping is more useful than speed.","instructions":["Use a clear level area","Begin at walking pace","Apply brakes smoothly and progressively","Complete ten controlled stops with space to spare."],"learningObjectives":["Use a clear level area","Complete 10 smooth controlled stops","Recognize and avoid the common mistake below."],"commonMistakes":["Grabbing a brake abruptly or practicing near traffic."],"safetyNotes":["Check air, brakes and chain before every ride. Use a fitted helmet and follow local traffic rules. Fixed-gear road use needs a functional front brake; do not learn brakeless street riding."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Sheldon Brown: Fixed Gear for the Road","url":"https://www.sheldonbrown.com/fixed.html","placeholder":false,"checkedAt":"2026-09-21"},{"title":"League of American Bicyclists: Learn to Ride (free course)","url":"https://learn.bikeleague.org/p/learntoride","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
