insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='swimming'),'swi-start','Welcome to Swimming','{"id":"swi-start","hobbyId":"swimming","slug":"swi-start","title":"Welcome to Swimming","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Choose comfort level and pool access","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":38,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":450,"y":0},"shortDescription":"Comfort and a safe learning environment come first.","whyItMatters":"Comfort and a safe learning environment come first.","instructions":["Describe your current comfort level honestly","Find a lifeguarded pool and qualified instruction","Choose a modest first goal."],"learningObjectives":["Describe your current comfort level honestly","Choose comfort level and pool access","Recognize and avoid the common mistake below."],"commonMistakes":["Assuming fitness on land means water competence."],"safetyNotes":["Practice with qualified supervision in a swim-safe environment. Never swim alone, hyperventilate or do breath-holding contests. Restrictive knee bands are not a default freestyle correction."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Red Cross Adult Swim Lessons","url":"https://www.redcross.org/take-a-class/swimming/swim-lessons/adult-swim-lessons","placeholder":false,"checkedAt":"2026-09-21"},{"title":"MySwimPro: How to swim freestyle for beginners","url":"https://blog.myswimpro.com/2021/06/04/how-to-swim-freestyle-for-beginners-5-step-guide/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=e