insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='journaling'),'jou-90','Ninety-Day Practice','{"id":"jou-90","hobbyId":"journaling","slug":"jou-90","title":"Ninety-Day Practice","tier":"advanced","nodeType":"milestone","xpReward":300,"requires":["jou-review"],"orGroups":[],"completion":{"prompt":"Complete personally chosen cadence over 90 days; no perfect streak required","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":71,"tags":["Creativity","Wellness"],"category":"Milestones","position":{"x":990,"y":900},"shortDescription":"A lasting practice can include breaks and adjustments.","whyItMatters":"A lasting practice can include breaks and adjustments.","instructions":["Choose a realistic cadence for ninety days","Keep entries as short as useful","Review and adjust occasionally","Reflect at the end without requiring a perfect streak."],"learningObjectives":["Choose a realistic cadence for ninety days","Complete personally chosen cadence over 90 days; no perfect streak required","Recognize and avoid the common mistake below."],"commonMistakes":["Using missed days to erase real progress."],"safetyNotes":[],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Bullet Journal: How to start a simple bullet journal","url":"https://bulletjournal.com/blogs/bulletjournalist/how-to-start-a-simple-bullet-journal","placeholder":false,"checkedAt":"2026-09-21"},{"title":"UC Berkeley Greater Good in Action: Expressive writing","url":"https://ggia.berkeley.edu/practice/expressive_writing","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-start','Welcome to PC Building','{"id":"pcb-start","hobbyId":"pc-building","slug":"pcb-start","title":"Welcome to PC Building","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read the overview and name the machine you want to build","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Practical","Knowledge"],"category":"Orientation","position":{"x":200,"y":0},"shortDescription":"A computer is a small number of parts that only fit together one way, and knowing what each one does removes most of the fear.","whyItMatters":"A computer is a small number of parts that only fit together one way, and knowing what each one does removes most of the fear.","instructions":["Read through what a CPU, motherboard, RAM, storage, power supply and case each do","Write down what you want the machine to be for","Note the rough budget you have in mind."],"learningObjectives":["Read through what a CPU, motherboard, RAM, storage, power supply and case each do","Read the overview and name the machine you want to build","Recognize and avoid the common mistake below."],"commonMistakes":["Buying parts before deciding what the machine is for, then discovering they do not suit it."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-safety','Electrical and ESD Safety','{"id":"pcb-safety","hobbyId":"pc-building","slug":"pcb-safety","title":"Electrical and ESD Safety","tier":"beginner","nodeType":"safety","xpReward":35,"requires":["pcb-start"],"orGroups":[],"completion":{"prompt":"Confirm you can work unplugged, grounded and on a safe surface","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Practical","Knowledge"],"category":"Safety","position":{"x":200,"y":150},"shortDescription":"Two things damage hardware and people: stored mains electricity and static discharge from your hands.","whyItMatters":"Two things damage hardware and people: stored mains electricity and static discharge from your hands.","instructions":["Unplug the power supply from the wall and hold the power button for five seconds before opening anything","Work on a hard non-carpet surface, not a bed or rug","Touch the bare metal case or wear a grounding strap before handling any board","Never open a power supply — it stores charge long after unplugging","Never work on a system that is plugged in."],"learningObjectives":["Unplug the power supply from the wall and hold the power button for five seconds before opening anything","Confirm you can work unplugged, grounded and on a safe surface","Recognize and avoid the common mistake below."],"commonMistakes":["Building on carpet while wearing a fleece, then blaming a dead board on the seller."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-gear','Parts and Tools','{"id":"pcb-gear","hobbyId":"pc-building","slug":"pcb-gear","title":"Parts and Tools","tier":"beginner","nodeType":"gear","xpReward":25,"requires":["pcb-safety"],"orGroups":[],"completion":{"prompt":"Record the parts and tools you have or can borrow","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Practical"],"category":"Gear","position":{"x":430,"y":150},"shortDescription":"A build needs fewer tools than people expect, and most of the cost is in parts you can buy used.","whyItMatters":"A build needs fewer tools than people expect, and most of the cost is in parts you can buy used.","instructions":["List the parts you already have, including from an old machine","Check that your motherboard socket and RAM type match your CPU","Borrow or buy a single Phillips screwdriver rather than a kit."],"learningObjectives":["List the parts you already have, including from an old machine","Record the parts and tools you have or can borrow","Recognize and avoid the common mistake below."],"commonMistakes":["Buying a large tool kit for a job that needs one screwdriver and patience."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-compat','Check Part Compatibility','{"id":"pcb-compat","hobbyId":"pc-building","slug":"pcb-compat","title":"Check Part Compatibility","tier":"beginner","nodeType":"knowledge","xpReward":40,"requires":["pcb-gear"],"orGroups":[],"completion":{"prompt":"Verify socket, RAM type, wattage and clearances for your list","evidenceMode":"note"},"estimatedMinutes":30,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Knowledge","Practical"],"category":"Planning","position":{"x":660,"y":150},"shortDescription":"Almost every failed build is a compatibility mistake made on paper, days before anything is unboxed.","whyItMatters":"Almost every failed build is a compatibility mistake made on paper, days before anything is unboxed.","instructions":["Confirm the CPU socket matches the motherboard socket exactly","Confirm the RAM generation matches what the board accepts","Add up the power draw and leave headroom on the supply","Check the cooler height and the graphics card length against the case specifications."],"learningObjectives":["Confirm the CPU socket matches the motherboard socket exactly","Verify socket, RAM type, wattage and clearances for your list","Recognize and avoid the common mistake below."],"commonMistakes":["Assuming that parts from the same brand or the same year will fit each other."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-bench','Bench Test Before Assembly','{"id":"pcb-bench","hobbyId":"pc-building","slug":"pcb-bench","title":"Bench Test Before Assembly","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["pcb-compat"],"orGroups":[],"completion":{"prompt":"Post the system outside the case with the minimum parts","evidenceMode":"note"},"estimatedMinutes":45,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Practical"],"category":"Assembly","position":{"x":890,"y":150},"shortDescription":"Testing the core parts on the box they came in finds a dead component before it is buried under cables.","whyItMatters":"Testing the core parts on the box they came in finds a dead component before it is buried under cables.","instructions":["Seat the CPU, one stick of RAM and the cooler on the motherboard outside the case","Connect the power supply and a display","Start the board and confirm it reaches firmware","Power down and unplug before moving anything."],"learningObjectives":["Seat the CPU, one stick of RAM and the cooler on the motherboard outside the case","Post the system outside the case with the minimum parts","Recognize and avoid the common mistake below."],"commonMistakes":["Assembling everything into the case first, then having to strip it back down to find the fault."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-assemble','First Full Assembly','{"id":"pcb-assemble","hobbyId":"pc-building","slug":"pcb-assemble","title":"First Full Assembly","tier":"intermediate","nodeType":"practice","xpReward":75,"requires":["pcb-bench"],"orGroups":[],"completion":{"prompt":"Complete a working build and reach the firmware screen","evidenceMode":"note"},"estimatedMinutes":120,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Practical"],"category":"Assembly","position":{"x":200,"y":300},"shortDescription":"Assembly is mostly ordering: parts that go in last are the hardest to reach past.","whyItMatters":"Assembly is mostly ordering: parts that go in last are the hardest to reach past.","instructions":["Mount the standoffs and the motherboard, then the power supply","Route the main cables behind the tray before fitting the board","Fit storage and the graphics card last","Connect the front panel header carefully, checking polarity."],"learningObjectives":["Mount the standoffs and the motherboard, then the power supply","Complete a working build and reach the firmware screen","Recognize and avoid the common mistake below."],"commonMistakes":["Fitting the graphics card early, then working around it for every other connection."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-bios','Firmware and First Boot','{"id":"pcb-bios","hobbyId":"pc-building","slug":"pcb-bios","title":"Firmware and First Boot","tier":"intermediate","nodeType":"knowledge","xpReward":60,"requires":["pcb-assemble"],"orGroups":[],"completion":{"prompt":"Set boot order, enable the memory profile, and install an operating system","evidenceMode":"note"},"estimatedMinutes":60,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Knowledge","Practical"],"category":"Software","position":{"x":430,"y":300},"shortDescription":"A finished build is not done until firmware and the operating system agree about what hardware exists.","whyItMatters":"A finished build is not done until firmware and the operating system agree about what hardware exists.","instructions":["Enter firmware setup and confirm every part is detected","Enable the memory profile so RAM runs at its rated speed","Set the boot device and install the operating system","Install chipset and graphics drivers before anything else."],"learningObjectives":["Enter firmware setup and confirm every part is detected","Set boot order, enable the memory profile, and install an operating system","Recognize and avoid the common mistake below."],"commonMistakes":["Leaving memory at its fallback speed for months without noticing."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-thermals','Cable Management and Thermals','{"id":"pcb-thermals","hobbyId":"pc-building","slug":"pcb-thermals","title":"Cable Management and Thermals","tier":"intermediate","nodeType":"practice","xpReward":65,"requires":["pcb-bios"],"orGroups":[],"completion":{"prompt":"Record idle and load temperatures after tidying airflow","evidenceMode":"duration","targetValue":20,"targetUnit":"minutes"},"estimatedMinutes":60,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Practical","Knowledge"],"category":"Tuning","position":{"x":660,"y":300},"shortDescription":"Cables are not only cosmetic: they sit in the path air needs to take through the case.","whyItMatters":"Cables are not only cosmetic: they sit in the path air needs to take through the case.","instructions":["Route cables behind the motherboard tray and secure them","Set intake and exhaust so air crosses the components once","Run a load test and record the peak CPU temperature","Compare it against the idle figure."],"learningObjectives":["Route cables behind the motherboard tray and secure them","Record idle and load temperatures after tidying airflow","Recognize and avoid the common mistake below."],"commonMistakes":["Chasing a quieter fan curve before fixing the airflow that made the fans loud."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='pc-building'),'pcb-diagnose','Diagnose a Faulty Build','{"id":"pcb-diagnose","hobbyId":"pc-building","slug":"pcb-diagnose","title":"Diagnose a Faulty Build","tier":"advanced","nodeType":"milestone","xpReward":90,"requires":["pcb-thermals"],"orGroups":[],"completion":{"prompt":"Work a no-POST or instability fault back to its cause","evidenceMode":"note"},"estimatedMinutes":90,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":8,"tags":["Knowledge","Practical"],"category":"Troubleshooting","position":{"x":200,"y":450},"shortDescription":"Diagnosis is subtraction: the fastest route to a cause is removing everything that is not needed to start.","whyItMatters":"Diagnosis is subtraction: the fastest route to a cause is removing everything that is not needed to start.","instructions":["Strip back to CPU, one RAM stick, and integrated display output","Reseat each part in turn and test between changes","Check the front panel header and the supply connectors before suspecting a board","Change only one variable at a time and write down what you tried."],"learningObjectives":["Strip back to CPU, one RAM stick, and integrated display output","Work a no-POST or instability fault back to its cause","Recognize and avoid the common mistake below."],"commonMistakes":["Replacing parts in the order they are expensive rather than the order they are likely."],"safetyNotes":["Unplug at the wall and hold the power button before opening anything. Ground yourself against the bare case or use a strap before touching a board, and never open a power supply — it holds charge long after it is unplugged."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"PCPartPicker Build Guides","url":"https://pcpartpicker.com/guide/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Linus Tech Tips: How to build a PC (video)","url":"https://www.youtube.com/watch?v=BL4DCEp7blY","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-start','Welcome to Drawing','{"id":"drw-start","hobbyId":"drawing","slug":"drw-start","title":"Welcome to Drawing","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read the overview and make one mark on paper","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Creativity","Knowledge"],"category":"Orientation","position":{"x":200,"y":0},"shortDescription":"Drawing is a looking skill before it is a hand skill, and the entry cost is a pencil and any paper you already own.","whyItMatters":"Drawing is a looking skill before it is a hand skill, and the entry cost is a pencil and any paper you already own.","instructions":["Find any pencil and any paper","Make a single deliberate line and look at it","Decide what you would like to be able to draw in a month."],"learningObjectives":["Find any pencil and any paper","Read the overview and make one mark on paper","Recognize and avoid the common mistake below."],"commonMistakes":["Waiting for better materials before making the first mark."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-gear','Pencil, Paper, Eraser','{"id":"drw-gear","hobbyId":"drawing","slug":"drw-gear","title":"Pencil, Paper, Eraser","tier":"beginner","nodeType":"gear","xpReward":20,"requires":["drw-safety"],"orGroups":[],"completion":{"prompt":"Record the drawing materials you already have","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Practical"],"category":"Gear","position":{"x":200,"y":150},"shortDescription":"Almost everything needed is already in the house, and cheap paper encourages the volume beginners need.","whyItMatters":"Almost everything needed is already in the house, and cheap paper encourages the volume beginners need.","instructions":["Find a pencil, some paper and an eraser","Choose the cheapest paper you are willing to fill","Keep them together so starting takes no setup."],"learningObjectives":["Find a pencil, some paper and an eraser","Record the drawing materials you already have","Recognize and avoid the common mistake below."],"commonMistakes":["Buying a expensive sketchbook that feels too precious to practise in."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-safety','Hands, Eyes and Posture','{"id":"drw-safety","hobbyId":"drawing","slug":"drw-safety","title":"Hands, Eyes and Posture","tier":"beginner","nodeType":"safety","xpReward":25,"requires":["drw-start"],"orGroups":[],"completion":{"prompt":"Set up a position you can hold comfortably and confirm your breaks","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Wellness"],"category":"Safety","position":{"x":430,"y":150},"shortDescription":"The injuries drawing causes are slow ones: strained wrists, tired eyes and a stiff neck from a bad angle.","whyItMatters":"The injuries drawing causes are slow ones: strained wrists, tired eyes and a stiff neck from a bad angle.","instructions":["Set the paper at an angle rather than flat so your wrist stays neutral","Draw from the shoulder and elbow for large shapes, not the fingers","Take a short break every twenty to thirty minutes and look at something far away","Work with light coming across the page rather than behind you","Stop if your hand or wrist aches rather than working through it."],"learningObjectives":["Set the paper at an angle rather than flat so your wrist stays neutral","Set up a position you can hold comfortably and confirm your breaks","Recognize and avoid the common mistake below."],"commonMistakes":["Drawing hunched over a flat desk for two hours and calling the resulting ache progress."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-lines','Line Confidence','{"id":"drw-lines","hobbyId":"drawing","slug":"drw-lines","title":"Line Confidence","tier":"beginner","nodeType":"practice","xpReward":40,"requires":["drw-gear"],"orGroups":[],"completion":{"prompt":"Fill a page with deliberate lines, circles and ellipses","evidenceMode":"duration","targetValue":20,"targetUnit":"minutes"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Creativity"],"category":"Fundamentals","position":{"x":660,"y":150},"shortDescription":"A confident line drawn once reads better than a careful line drawn five times.","whyItMatters":"A confident line drawn once reads better than a careful line drawn five times.","instructions":["Fill a page with long straight lines drawn in one movement","Add rows of circles and ellipses","Keep the pencil moving rather than sketching in short strokes","Do not erase anything on this page."],"learningObjectives":["Fill a page with long straight lines drawn in one movement","Fill a page with deliberate lines, circles and ellipses","Recognize and avoid the common mistake below."],"commonMistakes":["Scratching at a line in short hairy strokes instead of committing to it."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-shapes','Seeing in Basic Shapes','{"id":"drw-shapes","hobbyId":"drawing","slug":"drw-shapes","title":"Seeing in Basic Shapes","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["drw-lines"],"orGroups":[],"completion":{"prompt":"Break three real objects down into simple shapes","evidenceMode":"note"},"estimatedMinutes":30,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Creativity","Knowledge"],"category":"Fundamentals","position":{"x":890,"y":150},"shortDescription":"Complicated objects are simple shapes in an arrangement, and finding the arrangement is most of the work.","whyItMatters":"Complicated objects are simple shapes in an arrangement, and finding the arrangement is most of the work.","instructions":["Choose three objects around you","Sketch each one as boxes, cylinders and spheres before any detail","Check the proportions against the real object by eye","Only then add the edges that make it recognisable."],"learningObjectives":["Choose three objects around you","Break three real objects down into simple shapes","Recognize and avoid the common mistake below."],"commonMistakes":["Starting with the outline and the details, then finding the proportions are wrong."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-values','Light and Shadow','{"id":"drw-values","hobbyId":"drawing","slug":"drw-values","title":"Light and Shadow","tier":"intermediate","nodeType":"practice","xpReward":65,"requires":["drw-shapes"],"orGroups":[],"completion":{"prompt":"Shade one object from a single light source","evidenceMode":"note"},"estimatedMinutes":40,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Creativity"],"category":"Rendering","position":{"x":200,"y":300},"shortDescription":"Form appears when values do, and a single light source makes the values obvious.","whyItMatters":"Form appears when values do, and a single light source makes the values obvious.","instructions":["Light one object with a single lamp","Identify the lightest area, the core shadow and the cast shadow","Build the dark areas up in layers rather than pressing hard","Leave the highlight as untouched paper."],"learningObjectives":["Light one object with a single lamp","Shade one object from a single light source","Recognize and avoid the common mistake below."],"commonMistakes":["Shading evenly all over, which flattens the object rather than turning it."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-gesture','Gesture and Movement','{"id":"drw-gesture","hobbyId":"drawing","slug":"drw-gesture","title":"Gesture and Movement","tier":"intermediate","nodeType":"practice","xpReward":65,"requires":["drw-lines"],"orGroups":[],"completion":{"prompt":"Draw twenty quick gesture studies of people or animals","evidenceMode":"count","targetValue":20,"targetUnit":"drawings"},"estimatedMinutes":30,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Creativity"],"category":"Observation","position":{"x":430,"y":300},"shortDescription":"Gesture captures what a figure is doing before what it looks like, and speed is what forces the choice.","whyItMatters":"Gesture captures what a figure is doing before what it looks like, and speed is what forces the choice.","instructions":["Set a timer for thirty seconds per pose","Draw the line of action first, from head through the spine","Keep the whole figure on the page, however rough","Move on when the timer sounds, even mid-line."],"learningObjectives":["Set a timer for thirty seconds per pose","Draw twenty quick gesture studies of people or animals","Recognize and avoid the common mistake below."],"commonMistakes":["Trying to make a thirty-second study look finished."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='drawing'),'drw-study','A Finished Study','{"id":"drw-study","hobbyId":"drawing","slug":"drw-study","title":"A Finished Study","tier":"advanced","nodeType":"milestone","xpReward":90,"requires":["drw-values","drw-gesture"],"orGroups":[],"completion":{"prompt":"Complete one drawing you are willing to show someone","evidenceMode":"note"},"estimatedMinutes":90,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Creativity"],"category":"Milestone","position":{"x":200,"y":450},"shortDescription":"Finishing teaches things that practice pages cannot, because finishing forces decisions about what matters.","whyItMatters":"Finishing teaches things that practice pages cannot, because finishing forces decisions about what matters.","instructions":["Choose a subject you have already practised","Block in the large shapes and check proportion before detail","Build values from light to dark","Stop when it reads, not when there is nowhere left to draw."],"learningObjectives":["Choose a subject you have already practised","Complete one drawing you are willing to show someone","Recognize and avoid the common mistake below."],"commonMistakes":["Adding detail to a drawing whose proportions were never checked."],"safetyNotes":["Keep the wrist neutral and draw from the shoulder for large shapes. Take a short break every twenty to thirty minutes, work with light across the page, and stop if your hand aches."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Drawabox Lesson 0: Getting started","url":"https://drawabox.com/lesson/0","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Proko: Drawing Basics (video playlist)","url":"https://www.youtube.com/playlist?list=PLtG4P3lq8RHHMNwxuVk0IcGRtPGHi4vN9","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-start','Welcome to Painting','{"id":"pnt-start","hobbyId":"painting","slug":"pnt-start","title":"Welcome to Painting","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read the overview and choose acrylic, watercolour or oil","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Creativity","Knowledge"],"category":"Orientation","position":{"x":200,"y":0},"shortDescription":"Paint behaves differently depending on what carries the pigment, and choosing that carrier is the first real decision.","whyItMatters":"Paint behaves differently depending on what carries the pigment, and choosing that carrier is the first real decision.","instructions":["Read what separates acrylic, watercolour and oil in drying time and clean-up","Pick one to start with, acrylic being the most forgiving","Note what you would like to paint first."],"learningObjectives":["Read what separates acrylic, watercolour and oil in drying time and clean-up","Read the overview and choose acrylic, watercolour or oil","Recognize and avoid the common mistake below."],"commonMistakes":["Starting with oils because they look serious, then abandoning them over solvent and drying time."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-safety','Ventilation and Materials Safety','{"id":"pnt-safety","hobbyId":"painting","slug":"pnt-safety","title":"Ventilation and Materials Safety","tier":"beginner","nodeType":"safety","xpReward":35,"requires":["pnt-start"],"orGroups":[],"completion":{"prompt":"Confirm your ventilation, storage and clean-up plan","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Practical","Wellness"],"category":"Safety","position":{"x":200,"y":150},"shortDescription":"Water-based paint is mostly harmless; solvents and some pigments are not, and the risk is cumulative rather than dramatic.","whyItMatters":"Water-based paint is mostly harmless; solvents and some pigments are not, and the risk is cumulative rather than dramatic.","instructions":["Work where air moves — an open window is the minimum for any solvent","Keep solvents in sealed containers away from heat and never pour them down a drain","Do not eat, drink or point a brush with your mouth while painting","Wash hands before leaving the work area","Prefer acrylic or watercolour while you are learning so none of this applies."],"learningObjectives":["Work where air moves — an open window is the minimum for any solvent","Confirm your ventilation, storage and clean-up plan","Recognize and avoid the common mistake below."],"commonMistakes":["Using oils and solvents in a closed bedroom because the fumes did not seem strong."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-gear','A Minimal Palette','{"id":"pnt-gear","hobbyId":"painting","slug":"pnt-gear","title":"A Minimal Palette","tier":"beginner","nodeType":"gear","xpReward":25,"requires":["pnt-safety"],"orGroups":[],"completion":{"prompt":"Record the paints, brushes and surface you have or can borrow","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Practical"],"category":"Gear","position":{"x":430,"y":150},"shortDescription":"Three primaries, white, one or two brushes and any sealed surface will teach more than a forty-colour set.","whyItMatters":"Three primaries, white, one or two brushes and any sealed surface will teach more than a forty-colour set.","instructions":["Gather a red, a blue, a yellow and a white","Find one medium round brush and one flat","Use any primed surface, including cardboard sealed with house paint."],"learningObjectives":["Gather a red, a blue, a yellow and a white","Record the paints, brushes and surface you have or can borrow","Recognize and avoid the common mistake below."],"commonMistakes":["Buying a large set of colours before learning to mix the ones you already have."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-mixing','Mixing What You See','{"id":"pnt-mixing","hobbyId":"painting","slug":"pnt-mixing","title":"Mixing What You See","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["pnt-gear"],"orGroups":[],"completion":{"prompt":"Mix and record a ten-step value scale and three matched colours","evidenceMode":"note"},"estimatedMinutes":40,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Creativity","Knowledge"],"category":"Fundamentals","position":{"x":660,"y":150},"shortDescription":"Almost any colour can be mixed from three primaries and white, and mixing teaches colour faster than buying it.","whyItMatters":"Almost any colour can be mixed from three primaries and white, and mixing teaches colour faster than buying it.","instructions":["Paint a ten-step scale from white to your darkest mix","Choose three real objects and mix a match for each","Write down what went into each mix","Compare the dried result, which will differ from the wet one."],"learningObjectives":["Paint a ten-step scale from white to your darkest mix","Mix and record a ten-step value scale and three matched colours","Recognize and avoid the common mistake below."],"commonMistakes":["Judging a mix while wet, then finding acrylic has dried noticeably darker."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-strokes','Brush Control','{"id":"pnt-strokes","hobbyId":"painting","slug":"pnt-strokes","title":"Brush Control","tier":"beginner","nodeType":"practice","xpReward":40,"requires":["pnt-gear"],"orGroups":[],"completion":{"prompt":"Fill a sheet with controlled strokes, edges and washes","evidenceMode":"duration","targetValue":20,"targetUnit":"minutes"},"estimatedMinutes":30,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Creativity"],"category":"Fundamentals","position":{"x":890,"y":150},"shortDescription":"The brush does most of the work if you let its shape and load do the talking.","whyItMatters":"The brush does most of the work if you let its shape and load do the talking.","instructions":["Practise a long even stroke with a loaded brush","Practise a dry-brush edge and a soft blended edge","Try a flat wash and a graded one","Notice how much paint the brush actually holds."],"learningObjectives":["Practise a long even stroke with a loaded brush","Fill a sheet with controlled strokes, edges and washes","Recognize and avoid the common mistake below."],"commonMistakes":["Scrubbing at the surface with a nearly dry brush and too little paint."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-still','A Simple Still Life','{"id":"pnt-still","hobbyId":"painting","slug":"pnt-still","title":"A Simple Still Life","tier":"intermediate","nodeType":"practice","xpReward":70,"requires":["pnt-mixing","pnt-strokes"],"orGroups":[],"completion":{"prompt":"Paint one object from life with a single light source","evidenceMode":"note"},"estimatedMinutes":60,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Creativity"],"category":"Composition","position":{"x":200,"y":300},"shortDescription":"A single object under one light is the smallest complete painting problem: shape, value, colour and edge.","whyItMatters":"A single object under one light is the smallest complete painting problem: shape, value, colour and edge.","instructions":["Set one object under one lamp","Block in the largest shapes in their mid values","Work from dark to light in opaque media, light to dark in watercolour","Keep the highlight until last."],"learningObjectives":["Set one object under one lamp","Paint one object from life with a single light source","Recognize and avoid the common mistake below."],"commonMistakes":["Beginning with the detail on the object rather than the shape of it."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-colour','Colour Relationships','{"id":"pnt-colour","hobbyId":"painting","slug":"pnt-colour","title":"Colour Relationships","tier":"intermediate","nodeType":"knowledge","xpReward":65,"requires":["pnt-mixing"],"orGroups":[],"completion":{"prompt":"Paint the same subject twice in two different colour schemes","evidenceMode":"note"},"estimatedMinutes":60,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Creativity","Knowledge"],"category":"Colour","position":{"x":430,"y":300},"shortDescription":"A colour is only right in relation to its neighbours, which is why the same object can be painted many ways.","whyItMatters":"A colour is only right in relation to its neighbours, which is why the same object can be painted many ways.","instructions":["Choose one simple subject","Paint it once in a warm scheme and once in a cool one","Keep the values the same in both","Compare which reads more clearly from across the room."],"learningObjectives":["Choose one simple subject","Paint the same subject twice in two different colour schemes","Recognize and avoid the common mistake below."],"commonMistakes":["Judging colours one at a time rather than against the ones beside them."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='painting'),'pnt-finish','A Finished Painting','{"id":"pnt-finish","hobbyId":"painting","slug":"pnt-finish","title":"A Finished Painting","tier":"advanced","nodeType":"milestone","xpReward":90,"requires":["pnt-still","pnt-colour"],"orGroups":[],"completion":{"prompt":"Complete and sign one painting","evidenceMode":"note"},"estimatedMinutes":120,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Creativity"],"category":"Milestone","position":{"x":200,"y":450},"shortDescription":"Finishing is a skill of its own, and the hardest part is recognising when more work makes a painting worse.","whyItMatters":"Finishing is a skill of its own, and the hardest part is recognising when more work makes a painting worse.","instructions":["Choose a subject you have already practised","Establish the big shapes and values before any detail","Step back at arm length regularly","Stop at the point where the next stroke would be decoration."],"learningObjectives":["Choose a subject you have already practised","Complete and sign one painting","Recognize and avoid the common mistake below."],"commonMistakes":["Overworking a painting that was finished twenty minutes earlier."],"safetyNotes":["Work where air moves, keep solvents sealed and away from heat, and never pour them down a drain. Do not eat or point a brush with your mouth. Acrylic and watercolour avoid nearly all of this while you learn."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"The Art Sherpa: Beginner acrylic painting course","url":"https://theartsherpa.com/BeginnerAcrylicPaintingCourse","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Will Kemp Art School: Acrylic painting for beginners","url":"https://willkempartschool.com/acrylic-painting/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-start','Welcome to Running','{"id":"run-start","hobbyId":"running","slug":"run-start","title":"Welcome to Running","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read the overview and choose a first route","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":200,"y":0},"shortDescription":"Running asks almost nothing to begin and punishes only one thing reliably, which is doing too much too soon.","whyItMatters":"Running asks almost nothing to begin and punishes only one thing reliably, which is doing too much too soon.","instructions":["Choose a flat, well-lit route you can reach on foot","Decide on a time rather than a distance for the first outing","Plan when in the week it will happen."],"learningObjectives":["Choose a flat, well-lit route you can reach on foot","Read the overview and choose a first route","Recognize and avoid the common mistake below."],"commonMistakes":["Choosing a distance goal on day one and treating anything less as failure."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-safety','Load, Traffic and Heat','{"id":"run-safety","hobbyId":"running","slug":"run-safety","title":"Load, Traffic and Heat","tier":"beginner","nodeType":"safety","xpReward":40,"requires":["run-start"],"orGroups":[],"completion":{"prompt":"Confirm your progression rule, visibility and hydration plan","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Athletics","Wellness"],"category":"Safety","position":{"x":200,"y":150},"shortDescription":"Most running injuries are load errors, and most running accidents are visibility errors. Both are avoidable by plan rather than by effort.","whyItMatters":"Most running injuries are load errors, and most running accidents are visibility errors. Both are avoidable by plan rather than by effort.","instructions":["Increase weekly time or distance gradually and take a lighter week roughly every fourth week","Run against traffic on roads without a path, and wear something reflective in low light","Carry or plan water in heat and slow down rather than pushing the same pace","Warm up by walking for five minutes before running","Treat new sharp pain as a reason to stop that session, not to run through it."],"learningObjectives":["Increase weekly time or distance gradually and take a lighter week roughly every fourth week","Confirm your progression rule, visibility and hydration plan","Recognize and avoid the common mistake below."],"commonMistakes":["Adding distance every single week because nothing hurt yet."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-gear','Shoes That Fit','{"id":"run-gear","hobbyId":"running","slug":"run-gear","title":"Shoes That Fit","tier":"beginner","nodeType":"gear","xpReward":25,"requires":["run-safety"],"orGroups":[],"completion":{"prompt":"Record the shoes and visibility gear you have or can borrow","evidenceMode":"honor"},"estimatedMinutes":20,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Practical"],"category":"Gear","position":{"x":430,"y":150},"shortDescription":"Fit and condition matter far more than model, and running shoes lose their cushioning long before they look worn.","whyItMatters":"Fit and condition matter far more than model, and running shoes lose their cushioning long before they look worn.","instructions":["Use any comfortable trainers you already own to start","Check there is roughly a thumb width in front of your longest toe","Note roughly how old they are and how much they have been used","Add something reflective if you will run in low light."],"learningObjectives":["Use any comfortable trainers you already own to start","Record the shoes and visibility gear you have or can borrow","Recognize and avoid the common mistake below."],"commonMistakes":["Buying shoes on appearance or on somebody else recommendation rather than on fit."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-walkrun','Walk-Run Intervals','{"id":"run-walkrun","hobbyId":"running","slug":"run-walkrun","title":"Walk-Run Intervals","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["run-gear"],"orGroups":[],"completion":{"prompt":"Complete a twenty-minute walk-run session","evidenceMode":"duration","targetValue":20,"targetUnit":"minutes"},"estimatedMinutes":25,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Athletics"],"category":"Fundamentals","position":{"x":660,"y":150},"shortDescription":"Alternating running and walking builds the same base with far less load than running continuously.","whyItMatters":"Alternating running and walking builds the same base with far less load than running continuously.","instructions":["Walk briskly for five minutes to warm up","Alternate one minute of easy running with two minutes of walking","Keep the running effort conversational","Finish with five minutes of walking."],"learningObjectives":["Walk briskly for five minutes to warm up","Complete a twenty-minute walk-run session","Recognize and avoid the common mistake below."],"commonMistakes":["Running the intervals hard, which turns an easy session into a hard one."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-easy','Finding Easy Pace','{"id":"run-easy","hobbyId":"running","slug":"run-easy","title":"Finding Easy Pace","tier":"beginner","nodeType":"practice","xpReward":50,"requires":["run-walkrun"],"orGroups":[],"completion":{"prompt":"Complete a continuous run at conversational pace","evidenceMode":"duration","targetValue":20,"targetUnit":"minutes"},"estimatedMinutes":30,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Athletics"],"category":"Fundamentals","position":{"x":890,"y":150},"shortDescription":"Most running should feel easier than beginners expect; easy pace is what lets the next session happen.","whyItMatters":"Most running should feel easier than beginners expect; easy pace is what lets the next session happen.","instructions":["Run at a pace where you could hold a conversation","Slow down whenever you cannot","Ignore pace numbers and go by breathing","Finish feeling you could have gone further."],"learningObjectives":["Run at a pace where you could hold a conversation","Complete a continuous run at conversational pace","Recognize and avoid the common mistake below."],"commonMistakes":["Treating every run as a test of how fast you can go today."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-cadence','Cadence and Form','{"id":"run-cadence","hobbyId":"running","slug":"run-cadence","title":"Cadence and Form","tier":"intermediate","nodeType":"practice","xpReward":65,"requires":["run-easy"],"orGroups":[],"completion":{"prompt":"Run one session counting and adjusting your step rate","evidenceMode":"note"},"estimatedMinutes":30,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Athletics","Knowledge"],"category":"Technique","position":{"x":200,"y":300},"shortDescription":"Small, frequent steps under your body reduce braking forces more reliably than any conscious change to foot strike.","whyItMatters":"Small, frequent steps under your body reduce braking forces more reliably than any conscious change to foot strike.","instructions":["Count your steps on one side for thirty seconds and double it","Try lifting that rate slightly by taking shorter steps, not faster legs","Keep your feet landing under your hips rather than ahead","Change one thing at a time and give it several sessions."],"learningObjectives":["Count your steps on one side for thirty seconds and double it","Run one session counting and adjusting your step rate","Recognize and avoid the common mistake below."],"commonMistakes":["Forcing a forefoot landing overnight and collecting a calf injury."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-long','Building a Longer Run','{"id":"run-long","hobbyId":"running","slug":"run-long","title":"Building a Longer Run","tier":"intermediate","nodeType":"practice","xpReward":75,"requires":["run-easy"],"orGroups":[],"completion":{"prompt":"Complete a run meaningfully longer than your usual one","evidenceMode":"duration","targetValue":20,"targetUnit":"minutes"},"estimatedMinutes":60,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Athletics"],"category":"Endurance","position":{"x":430,"y":300},"shortDescription":"One longer, slower run each week builds endurance better than making every run a little longer.","whyItMatters":"One longer, slower run each week builds endurance better than making every run a little longer.","instructions":["Choose one run a week to extend","Go slower than your usual easy pace","Increase it gradually rather than in jumps","Plan water and a route you can cut short."],"learningObjectives":["Choose one run a week to extend","Complete a run meaningfully longer than your usual one","Recognize and avoid the common mistake below."],"commonMistakes":["Extending every run at once rather than one of them."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='running'),'run-race','A First Event or Distance Goal','{"id":"run-race","hobbyId":"running","slug":"run-race","title":"A First Event or Distance Goal","tier":"advanced","nodeType":"milestone","xpReward":95,"requires":["run-long","run-cadence"],"orGroups":[],"completion":{"prompt":"Complete a chosen distance or a local event","evidenceMode":"note"},"estimatedMinutes":90,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Athletics"],"category":"Milestone","position":{"x":200,"y":450},"shortDescription":"A date on the calendar changes how training feels, and finishing a first one is about pacing rather than fitness.","whyItMatters":"A date on the calendar changes how training feels, and finishing a first one is about pacing rather than fitness.","instructions":["Choose a realistic distance and a date several weeks out","Keep the week before deliberately light","Start slower than feels right for the first third","Finish knowing what you would do differently."],"learningObjectives":["Choose a realistic distance and a date several weeks out","Complete a chosen distance or a local event","Recognize and avoid the common mistake below."],"commonMistakes":["Starting far too fast because everyone around you did."],"safetyNotes":["Build distance gradually and take a lighter week roughly every fourth. Run facing traffic where there is no path, wear something reflective in low light, plan water in heat, and treat new sharp pain as a reason to stop."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"RRCA 10-week training plan for new runners","url":"https://www.rrca.org/education/for-runners/10-week-training-plan/","placeholder":false,"checkedAt":"2026-09-21"},{"title":"NHS: Get running with Couch to 5K","url":"https://www.nhs.uk/better-health/get-active/get-running-with-couch-to-5k/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-start','Welcome to Volleyball','{"id":"vol-start","hobbyId":"volleyball","slug":"vol-start","title":"Welcome to Volleyball","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read the overview and find somewhere people play","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Athletics","Knowledge"],"category":"Orientation","position":{"x":200,"y":0},"shortDescription":"Volleyball is one of the few sports where a complete beginner is welcome in a casual game on the first day.","whyItMatters":"Volleyball is one of the few sports where a complete beginner is welcome in a casual game on the first day.","instructions":["Find a local open gym, beach net or recreational session","Read the basic rotation and scoring rules","Note when you could realistically turn up."],"learningObjectives":["Find a local open gym, beach net or recreational session","Read the overview and find somewhere people play","Recognize and avoid the common mistake below."],"commonMistakes":["Waiting until you feel good enough to join a casual session that exists for beginners."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-safety','Warm-Up, Fingers and Ankles','{"id":"vol-safety","hobbyId":"volleyball","slug":"vol-safety","title":"Warm-Up, Fingers and Ankles","tier":"beginner","nodeType":"safety","xpReward":40,"requires":["vol-start"],"orGroups":[],"completion":{"prompt":"Confirm your warm-up and landing habits","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Athletics","Wellness"],"category":"Safety","position":{"x":200,"y":150},"shortDescription":"Volleyball injuries cluster in two places: fingers meeting a ball at the wrong angle, and ankles landing on someone else foot.","whyItMatters":"Volleyball injuries cluster in two places: fingers meeting a ball at the wrong angle, and ankles landing on someone else foot.","instructions":["Warm up the shoulders, wrists and ankles before hitting anything","Set with firm fingers and a relaxed wrist rather than soft fingertips","Land on two feet and avoid stepping under the net into another player space","Call for the ball loudly so two players do not collide","Stop if a finger or ankle takes a sharp twist rather than taping it and continuing."],"learningObjectives":["Warm up the shoulders, wrists and ankles before hitting anything","Confirm your warm-up and landing habits","Recognize and avoid the common mistake below."],"commonMistakes":["Going straight into hitting hard without warming the shoulder up first."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-gear','Shoes, Pads and a Ball','{"id":"vol-gear","hobbyId":"volleyball","slug":"vol-gear","title":"Shoes, Pads and a Ball","tier":"beginner","nodeType":"gear","xpReward":25,"requires":["vol-safety"],"orGroups":[],"completion":{"prompt":"Record the kit you have or can borrow","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Practical"],"category":"Gear","position":{"x":430,"y":150},"shortDescription":"Most volleyball equipment is shared or provided, and indoor courts mostly ask for clean non-marking soles.","whyItMatters":"Most volleyball equipment is shared or provided, and indoor courts mostly ask for clean non-marking soles.","instructions":["Check whether the session provides balls and a net, which most do","Use clean indoor trainers with non-marking soles","Borrow knee pads before buying, and skip them entirely for beach."],"learningObjectives":["Check whether the session provides balls and a net, which most do","Record the kit you have or can borrow","Recognize and avoid the common mistake below."],"commonMistakes":["Buying a full kit before finding out the session supplies everything but shoes."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-pass','The Forearm Pass','{"id":"vol-pass","hobbyId":"volleyball","slug":"vol-pass","title":"The Forearm Pass","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["vol-gear"],"orGroups":[],"completion":{"prompt":"Complete fifty controlled passes against a wall or partner","evidenceMode":"count","targetValue":50,"targetUnit":"passes"},"estimatedMinutes":25,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Athletics"],"category":"Fundamentals","position":{"x":660,"y":150},"shortDescription":"The pass is the first contact in almost every rally, and a good one makes everything after it possible.","whyItMatters":"The pass is the first contact in almost every rally, and a good one makes everything after it possible.","instructions":["Join your hands with thumbs parallel and arms straight","Move your feet so the ball arrives in front of your midline","Let the ball rebound off the forearms rather than swinging at it","Finish facing where you want the ball to go."],"learningObjectives":["Join your hands with thumbs parallel and arms straight","Complete fifty controlled passes against a wall or partner","Recognize and avoid the common mistake below."],"commonMistakes":["Swinging the arms at the ball instead of letting it come to a platform."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-set','Setting Overhead','{"id":"vol-set","hobbyId":"volleyball","slug":"vol-set","title":"Setting Overhead","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["vol-pass"],"orGroups":[],"completion":{"prompt":"Complete fifty controlled sets","evidenceMode":"count","targetValue":50,"targetUnit":"sets"},"estimatedMinutes":25,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Athletics"],"category":"Fundamentals","position":{"x":890,"y":150},"shortDescription":"Setting is the most controllable contact in the game and the one that most rewards clean hand shape.","whyItMatters":"Setting is the most controllable contact in the game and the one that most rewards clean hand shape.","instructions":["Form a window with your hands above your forehead","Take the ball with the pads of the fingers, not the palms","Extend legs and arms together through the ball","Keep it quiet — noise means the ball hit your palms."],"learningObjectives":["Form a window with your hands above your forehead","Complete fifty controlled sets","Recognize and avoid the common mistake below."],"commonMistakes":["Catching and throwing the ball, which is both a fault and a habit that is hard to unlearn."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-serve','A Reliable Serve','{"id":"vol-serve","hobbyId":"volleyball","slug":"vol-serve","title":"A Reliable Serve","tier":"intermediate","nodeType":"practice","xpReward":60,"requires":["vol-set"],"orGroups":[],"completion":{"prompt":"Land seven of ten serves in play","evidenceMode":"count","targetValue":7,"targetUnit":"serves"},"estimatedMinutes":30,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Athletics"],"category":"Technique","position":{"x":200,"y":300},"shortDescription":"A serve that lands is worth more than a powerful one that does not, because every missed serve is a free point.","whyItMatters":"A serve that lands is worth more than a powerful one that does not, because every missed serve is a free point.","instructions":["Choose a consistent toss and repeat it before adding power","Contact the centre of the ball with a firm flat hand","Step into the serve rather than arming it","Aim for a large area rather than a line."],"learningObjectives":["Choose a consistent toss and repeat it before adding power","Land seven of ten serves in play","Recognize and avoid the common mistake below."],"commonMistakes":["Trying to serve hard before the toss is repeatable."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-attack','Approach and Attack','{"id":"vol-attack","hobbyId":"volleyball","slug":"vol-attack","title":"Approach and Attack","tier":"intermediate","nodeType":"practice","xpReward":70,"requires":["vol-serve"],"orGroups":[],"completion":{"prompt":"Complete a full approach and attack in a rally","evidenceMode":"note"},"estimatedMinutes":45,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Athletics"],"category":"Technique","position":{"x":430,"y":300},"shortDescription":"The approach is a rhythm rather than a run, and it is what turns a set into an attack.","whyItMatters":"The approach is a rhythm rather than a run, and it is what turns a set into an attack.","instructions":["Learn the footwork rhythm on the ground before adding a ball","Time the approach to the set rather than to the setter","Swing high with a full arm rather than pushing the ball","Land balanced on two feet."],"learningObjectives":["Learn the footwork rhythm on the ground before adding a ball","Complete a full approach and attack in a rally","Recognize and avoid the common mistake below."],"commonMistakes":["Jumping early and reaching up at a ball that has already dropped."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='volleyball'),'vol-game','Play a Full Game','{"id":"vol-game","hobbyId":"volleyball","slug":"vol-game","title":"Play a Full Game","tier":"advanced","nodeType":"milestone","xpReward":90,"requires":["vol-attack"],"orGroups":[],"completion":{"prompt":"Play a complete game in rotation","evidenceMode":"note"},"estimatedMinutes":90,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Athletics"],"category":"Milestone","position":{"x":200,"y":450},"shortDescription":"Rotation, calling and covering only make sense inside a real game, and they are most of what a team needs.","whyItMatters":"Rotation, calling and covering only make sense inside a real game, and they are most of what a team needs.","instructions":["Join a session and play in rotation","Call every ball you go for","Cover your hitter rather than watching the attack","Note afterwards which position felt least comfortable."],"learningObjectives":["Join a session and play in rotation","Play a complete game in rotation","Recognize and avoid the common mistake below."],"commonMistakes":["Standing still and watching the ball instead of moving to cover."],"safetyNotes":["Warm the shoulders, wrists and ankles before hitting. Set with firm fingers, land on two feet, keep out of the space under the net, and call loudly so nobody collides."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"USA Volleyball: A beginner''s guide (PDF)","url":"https://usavolleyball.org/wp-content/uploads/2022/03/Volleyball-Beginners-Guide-by-SportsEngine.pdf","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Elevate Yourself: Volleyball tutorials (video)","url":"https://www.youtube.com/@ElevateYourselfOfficial","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-start','Welcome to Reading','{"id":"rdg-start","hobbyId":"reading","slug":"rdg-start","title":"Welcome to Reading","tier":"start","nodeType":"orientation","xpReward":20,"requires":[],"orGroups":[],"completion":{"prompt":"Read the overview and choose one book to start","evidenceMode":"note"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":0,"tags":["Knowledge"],"category":"Orientation","position":{"x":200,"y":0},"shortDescription":"Reading more is rarely about discipline; it is about lowering the cost of starting and choosing books you actually want.","whyItMatters":"Reading more is rarely about discipline; it is about lowering the cost of starting and choosing books you actually want.","instructions":["Choose one book you genuinely want to read, not one you feel you should","Decide where it will live so it is always to hand","Note when in the day reading could realistically fit."],"learningObjectives":["Choose one book you genuinely want to read, not one you feel you should","Read the overview and choose one book to start","Recognize and avoid the common mistake below."],"commonMistakes":["Starting with a book chosen for how it would look to have read."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-gear','A Library Card','{"id":"rdg-gear","hobbyId":"reading","slug":"rdg-gear","title":"A Library Card","tier":"beginner","nodeType":"gear","xpReward":20,"requires":["rdg-safety"],"orGroups":[],"completion":{"prompt":"Record your library access or the books you already own","evidenceMode":"honor"},"estimatedMinutes":15,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":1,"tags":["Practical","Knowledge"],"category":"Gear","position":{"x":200,"y":150},"shortDescription":"A library card makes this hobby free, and most also lend ebooks and audiobooks to a phone.","whyItMatters":"A library card makes this hobby free, and most also lend ebooks and audiobooks to a phone.","instructions":["Find your nearest public library and what it needs to issue a card","Check whether it lends ebooks or audiobooks","Otherwise gather the unread books you already own."],"learningObjectives":["Find your nearest public library and what it needs to issue a card","Record your library access or the books you already own","Recognize and avoid the common mistake below."],"commonMistakes":["Buying books faster than you read them and calling the pile a hobby."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-safety','Eyes, Light and Sleep','{"id":"rdg-safety","hobbyId":"reading","slug":"rdg-safety","title":"Eyes, Light and Sleep","tier":"beginner","nodeType":"safety","xpReward":25,"requires":["rdg-start"],"orGroups":[],"completion":{"prompt":"Set up comfortable light and a screen habit you can keep","evidenceMode":"honor"},"estimatedMinutes":10,"isRequired":true,"isSafetyCritical":true,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":2,"tags":["Wellness"],"category":"Safety","position":{"x":430,"y":150},"shortDescription":"Nothing here is dangerous, but bad light, bad posture and late screens quietly make reading unpleasant.","whyItMatters":"Nothing here is dangerous, but bad light, bad posture and late screens quietly make reading unpleasant.","instructions":["Read with light falling on the page rather than behind it","Hold the book or screen at roughly eye level to save your neck","Look at something distant for a few seconds every twenty minutes","Dim screens in the evening and prefer paper near bedtime","Stop if your eyes ache rather than pushing to the end of the chapter."],"learningObjectives":["Read with light falling on the page rather than behind it","Set up comfortable light and a screen habit you can keep","Recognize and avoid the common mistake below."],"commonMistakes":["Reading on a bright phone in a dark room and blaming the book for the headache."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-habit','A Daily Reading Slot','{"id":"rdg-habit","hobbyId":"reading","slug":"rdg-habit","title":"A Daily Reading Slot","tier":"beginner","nodeType":"practice","xpReward":40,"requires":["rdg-gear"],"orGroups":[],"completion":{"prompt":"Read on five separate days this week","evidenceMode":"count","targetValue":5,"targetUnit":"days"},"estimatedMinutes":25,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":3,"tags":["Knowledge","Wellness"],"category":"Habit","position":{"x":660,"y":150},"shortDescription":"A small fixed slot beats a large ambitious one, because the small one survives a bad week.","whyItMatters":"A small fixed slot beats a large ambitious one, because the small one survives a bad week.","instructions":["Choose a time you already do something predictable","Start with ten minutes rather than an hour","Keep the book where that moment happens","Mark the days you read rather than the pages."],"learningObjectives":["Choose a time you already do something predictable","Read on five separate days this week","Recognize and avoid the common mistake below."],"commonMistakes":["Setting an hour a day, missing twice, and abandoning the whole thing."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-notes','Reading With a Pencil','{"id":"rdg-notes","hobbyId":"reading","slug":"rdg-notes","title":"Reading With a Pencil","tier":"beginner","nodeType":"practice","xpReward":45,"requires":["rdg-habit"],"orGroups":[],"completion":{"prompt":"Finish a book while keeping brief notes","evidenceMode":"note"},"estimatedMinutes":60,"isRequired":true,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":4,"tags":["Knowledge","Creativity"],"category":"Comprehension","position":{"x":890,"y":150},"shortDescription":"Marking a book as you go turns reading from something that passes through you into something that stays.","whyItMatters":"Marking a book as you go turns reading from something that passes through you into something that stays.","instructions":["Keep a pencil or a notes app with the book","Mark passages that surprise you rather than ones that sound important","Write one sentence at the end of each session about what happened","Review your marks when you finish."],"learningObjectives":["Keep a pencil or a notes app with the book","Finish a book while keeping brief notes","Recognize and avoid the common mistake below."],"commonMistakes":["Highlighting so much that nothing stands out on review."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-range','Reading Outside Your Lane','{"id":"rdg-range","hobbyId":"reading","slug":"rdg-range","title":"Reading Outside Your Lane","tier":"intermediate","nodeType":"practice","xpReward":60,"requires":["rdg-habit"],"orGroups":[],"completion":{"prompt":"Finish a book from a genre or form you do not usually read","evidenceMode":"note"},"estimatedMinutes":60,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":5,"tags":["Knowledge"],"category":"Range","position":{"x":200,"y":300},"shortDescription":"Range is what makes reading compound, because unfamiliar forms teach you how the familiar ones work.","whyItMatters":"Range is what makes reading compound, because unfamiliar forms teach you how the familiar ones work.","instructions":["Pick a form you avoid — poetry, essays, history, translated fiction","Give it fifty pages before deciding","Notice what the form does that your usual reading does not","Finish it or abandon it deliberately rather than by drift."],"learningObjectives":["Pick a form you avoid — poetry, essays, history, translated fiction","Finish a book from a genre or form you do not usually read","Recognize and avoid the common mistake below."],"commonMistakes":["Treating every abandoned book as a personal failure rather than a mismatch."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-discuss','Talk About What You Read','{"id":"rdg-discuss","hobbyId":"reading","slug":"rdg-discuss","title":"Talk About What You Read","tier":"intermediate","nodeType":"practice","xpReward":65,"requires":["rdg-notes"],"orGroups":[],"completion":{"prompt":"Discuss a finished book with someone, or write a short review","evidenceMode":"note"},"estimatedMinutes":45,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":6,"tags":["Knowledge","Creativity"],"category":"Reflection","position":{"x":430,"y":300},"shortDescription":"Explaining a book to someone else is the fastest way to find out what you actually took from it.","whyItMatters":"Explaining a book to someone else is the fastest way to find out what you actually took from it.","instructions":["Choose a book you have finished recently","Summarise it in a few sentences without notes","Say what you disagreed with as well as what you liked","Write it down if there is nobody to tell."],"learningObjectives":["Choose a book you have finished recently","Discuss a finished book with someone, or write a short review","Recognize and avoid the common mistake below."],"commonMistakes":["Summarising the plot rather than saying what the book was doing."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"https://bookriot.com/how-to-start-reading/","placeholder":false,"checkedAt":"2026-09-21"}]}'::jsonb) on conflict(slug) do update set content=excluded.content;
insert into public.skill_nodes(hobby_id,slug,title,content) values((select id from public.hobbies where slug='reading'),'rdg-project','A Reading Project','{"id":"rdg-project","hobbyId":"reading","slug":"rdg-project","title":"A Reading Project","tier":"advanced","nodeType":"milestone","xpReward":90,"requires":["rdg-range","rdg-discuss"],"orGroups":[],"completion":{"prompt":"Complete a self-set reading project","evidenceMode":"note"},"estimatedMinutes":120,"isRequired":false,"isSafetyCritical":false,"isRecommended":true,"status":"published","contentVersion":1,"sortOrder":7,"tags":["Knowledge"],"category":"Milestone","position":{"x":200,"y":450},"shortDescription":"A project — an author, a subject, a period — turns separate books into something cumulative.","whyItMatters":"A project — an author, a subject, a period — turns separate books into something cumulative.","instructions":["Choose a narrow subject, author or period","Pick three or four books that speak to each other","Keep notes across all of them, not each separately","Write a paragraph at the end on what changed in your view."],"learningObjectives":["Choose a narrow subject, author or period","Complete a self-set reading project","Recognize and avoid the common mistake below."],"commonMistakes":["Choosing a project so broad it becomes an unending reading list."],"safetyNotes":["Read with light on the page rather than behind it, hold the book near eye level, and look at something distant every twenty minutes. Dim screens in the evening and prefer paper near bedtime."],"mastery":{"prompt":"Repeat this challenge on three separate days and describe what became more consistent.","evidenceMode":"note"},"masteryXpReward":15,"review_status":"draft","last_reviewed_at":null,"resources":[{"title":"Libby: Getting started with free library ebooks","url":"https://help.libbyapp.com/en-us/6103.htm","placeholder":false,"checkedAt":"2026-09-21"},{"title":"Book Riot: How to start reading (if you''ve never liked it)","url":"http